#문자열 포맷팅( f-strings)
name = "pororo"
age = 23;

print(f"제 이름은 {name}이고, 나이는 {age}입니다.")
print(f"내년의 나이는 {age+1}입니다.")
print(f"{name.upper()}")

pi=3.
print(f"원주율은 {pi:.20f}입니다.")
print(f"원주율은 {pi:.0f}입니다.")

num = 1000000000
print(f"{num:,}입니다.")
print(f"{num:,.2f}입니다.")
print(f"{num:015,d}입니다.")

